def validate_schema(sch):
    if not isinstance(sch, list) or not (1 <= len(sch) <= 32):
        die("E_SCHEMA")
    fields = []
    names = set()
    for item in sch:
        if not isinstance(item, dict):
            die("E_SCHEMA")
        keys = set(item.keys())
        if "name" not in keys or "type" not in keys:
            die("E_SCHEMA")
        name = item["name"]
        ftype = item["type"]
        if not is_str(name) or RE_NAME.fullmatch(name) is None:
            die("E_SCHEMA")
        if name in names:
            die("E_SCHEMA")
        names.add(name)
        if not is_str(ftype) or ftype not in ALL_TYPES:
            die("E_SCHEMA")
        if ftype in NUMERIC_TYPES:
            if keys != {"name", "type", "min", "max"}:
                die("E_SCHEMA")
            lo = item["min"]
            hi = item["max"]
            if not is_i32(lo) or not is_i32(hi) or lo > hi:
                die("E_SCHEMA")
            fields.append({"name": name, "type": ftype, "min": lo, "max": hi,
                           "values": None})
        elif ftype == "ID":
            if keys != {"name", "type", "values"}:
                die("E_SCHEMA")
            vals = item["values"]
            if not isinstance(vals, list) or not (1 <= len(vals) <= 32):
                die("E_SCHEMA")
            vset = set()
            for v in vals:
                if not is_str(v) or RE_IDVAL.fullmatch(v) is None or v in vset:
                    die("E_SCHEMA")
                vset.add(v)
            fields.append({"name": name, "type": "ID", "min": None, "max": None,
                           "values": vset})
        else:  # FLAG
            if keys != {"name", "type"}:
                die("E_SCHEMA")
            fields.append({"name": name, "type": "FLAG", "min": None, "max": None,
                           "values": None})
    return fields


def validate_policy(pol):
    if not isinstance(pol, dict):
        die("E_SCHEMA")
    if set(pol.keys()) != {"max_width", "min_support", "min_witness"}:
        die("E_SCHEMA")
    width = pol["max_width"]
    supp = pol["min_support"]
    wit = pol["min_witness"]
    if not (is_int(width) and 1 <= width <= 4):
        die("E_SCHEMA")
    if not (is_int(supp) and 1 <= supp <= 4096):
        die("E_SCHEMA")
    if not (is_int(wit) and 1 <= wit <= 4096):
        die("E_SCHEMA")
    return width, supp, wit


